import{_ as a,o as i,c as t,a6 as r,bi as o,bj as l,bk as n,bl as s,bm as d,bn as c,bo as h}from"./chunks/framework.DhXJbKDf.js";const P=JSON.parse('{"title":"DSWP Team Pattern","description":"","frontmatter":{},"headers":[],"relativePath":"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPTeamPattern.md","filePath":"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPTeamPattern.md"}'),p={name:"content/themes/design-system-wordpress-theme/guide/SiteEditor/Patterns/DSWPTeamPattern.md"};function g(m,e,u,b,f,k){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="dswp-team-pattern" tabindex="-1">DSWP Team Pattern <a class="header-anchor" href="#dswp-team-pattern" aria-label="Permalink to “DSWP Team Pattern”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This pattern creates a series of team member profiles, alternating between white and light gray backgrounds. Each profile features a circular image, name, subtitle, and detailed biography in a two-column layout.</p><div class="warning custom-block"><p class="custom-block-title">Important Note</p><p>Each pattern consists of several blocks. Only adjust the content and color block settings. The structural settings (padding and margins) are pre-configured for responsiveness. Modifying structural settings may break the pattern.</p></div><h2 id="pattern-components" tabindex="-1">Pattern Components <a class="header-anchor" href="#pattern-components" aria-label="Permalink to “Pattern Components”">​</a></h2><p><img src="'+o+'" alt="Pattern Components"></p><p>Each team member section contains:</p><ol><li><p><strong>Image</strong></p><ul><li>180px width circular image</li><li>Aspect ratio 1:1</li><li>Object-fit: cover</li><li>Left-aligned</li></ul></li><li><p><strong>Heading</strong></p><ul><li>H5 heading (2.0 line height)</li></ul></li><li><p><strong>Subtitle</strong></p><ul><li>Italicized subtitle (H6 size)</li><li></li></ul></li><li><p><strong>Paragraph</strong></p><ul><li>Three paragraphs of biography</li></ul></li></ol><h3 id="section-container" tabindex="-1">Section Container <a class="header-anchor" href="#section-container" aria-label="Permalink to “Section Container”">​</a></h3><ul><li>Alternating backgrounds: <ul><li>White</li><li>Light gray</li></ul></li></ul><h2 id="common-tasks" tabindex="-1">Common Tasks <a class="header-anchor" href="#common-tasks" aria-label="Permalink to “Common Tasks”">​</a></h2><h3 id="profile-image" tabindex="-1">Profile Image <a class="header-anchor" href="#profile-image" aria-label="Permalink to “Profile Image”">​</a></h3><ol><li>Select the image block</li><li>Click &quot;Replace&quot;</li><li>Upload square image (automatically crops to circle)</li><li>Maintains 180px width and 1:1 ratio <img src="'+l+'" alt="Image replacement"></li></ol><h3 id="modifying-the-heading" tabindex="-1">Modifying the Heading <a class="header-anchor" href="#modifying-the-heading" aria-label="Permalink to “Modifying the Heading”">​</a></h3><ol><li>Click on the heading text</li><li>Type your new heading</li></ol><p><img src="'+n+'" alt="Modifying the Heading"></p><h3 id="modifying-the-sub-heading" tabindex="-1">Modifying the Sub-Heading <a class="header-anchor" href="#modifying-the-sub-heading" aria-label="Permalink to “Modifying the Sub-Heading”">​</a></h3><ol><li>Click on the sub-heading text</li><li>Type your new heading</li></ol><p><img src="'+s+'" alt="Modifying the Heading"></p><h3 id="modifying-the-paragraph" tabindex="-1">Modifying the Paragraph <a class="header-anchor" href="#modifying-the-paragraph" aria-label="Permalink to “Modifying the Paragraph”">​</a></h3><ol><li>Click to edit paragraph text</li><li>Start Typing new content</li></ol><p><img src="'+d+'" alt="Modifying the Paragraph"></p><h3 id="to-add-a-card" tabindex="-1">To Add a Card <a class="header-anchor" href="#to-add-a-card" aria-label="Permalink to “To Add a Card”">​</a></h3><ol><li>Click the ellipses (⋮) next to any profile card (see gif below)</li><li>Select &quot;Duplicate&quot;</li><li>Expand the new profile to see the group a layer down</li><li>Select block styles</li><li>Select background</li><li>This step depends on whether the previous profile has a background. If it has a background color, select clear in the color picker; otherwise, select &quot;light gray&quot;.</li></ol><p><img src="'+c+'" alt="Adding a Card"></p><h3 id="layout-considerations" tabindex="-1">Layout Considerations <a class="header-anchor" href="#layout-considerations" aria-label="Permalink to “Layout Considerations”">​</a></h3><ul><li>Desktop: Side-by-side layout</li><li>Tablet: Maintains side-by-side</li><li>Mobile: Stacks with image above content left aligned <img src="'+h+'" alt="Responsive behavior"></li></ul><h2 id="block-documentation" tabindex="-1">Block Documentation <a class="header-anchor" href="#block-documentation" aria-label="Permalink to “Block Documentation”">​</a></h2><p>For detailed instructions on modifying specific blocks, refer to WordPress&#39;s official documentation:</p><ul><li><a href="https://wordpress.com/support/wordpress-editor/blocks/image-block/" target="_blank" rel="noreferrer">Image Block</a></li><li><a href="https://wordpress.com/support/wordpress-editor/blocks/heading-block/" target="_blank" rel="noreferrer">Heading Block</a></li><li><a href="https://wordpress.com/support/wordpress-editor/blocks/paragraph-block/" target="_blank" rel="noreferrer">Paragraph Block</a></li></ul>',30)])])}const _=a(p,[["render",g]]);export{P as __pageData,_ as default};
